//! Actual native Tokio reactor and Mio source over an in-memory ABI simulator.
mod boundary;
mod network_boundary;
use std::{sync::atomic::Ordering,time::Duration};
use tokio::{io::{AsyncReadExt,AsyncWriteExt},net::{TcpListener,TcpStream,UdpSocket}};
fn current()->tokio::runtime::Runtime{tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap()}
fn test(name:&str,f:impl FnOnce()){f();assert_eq!(network_boundary::live_sockets(),0,"native socket ownership leaked after {name}");println!("ok {name}");}
fn main(){
 test("native async TCP fragmented request/reply",||{current().block_on(async{let listener=TcpListener::bind("127.0.0.1:0").await.unwrap();let addr=listener.local_addr().unwrap();let server=tokio::spawn(async move{let(mut peer,source)=listener.accept().await.unwrap();assert_eq!(peer.peer_addr().unwrap(),source);let mut request=[0;7];peer.read_exact(&mut request).await.unwrap();assert_eq!(&request,b"request");peer.write_all(b"response").await.unwrap();peer.shutdown().await.unwrap();});let mut client=TcpStream::connect(addr).await.unwrap();client.write_all(b"request").await.unwrap();let mut response=Vec::new();client.read_to_end(&mut response).await.unwrap();assert_eq!(response,b"response");server.await.unwrap();});});
 test("native TCP peek retains bytes and half-close retains reads",||{current().block_on(async{let listener=TcpListener::bind("127.0.0.1:0").await.unwrap();let mut a=TcpStream::connect(listener.local_addr().unwrap()).await.unwrap();let(mut b,_)=listener.accept().await.unwrap();a.write_all(b"hello").await.unwrap();a.shutdown().await.unwrap();let mut peek=[0;3];assert_eq!(b.peek(&mut peek).await.unwrap(),3);assert_eq!(&peek,b"hel");let mut message=Vec::new();b.read_to_end(&mut message).await.unwrap();assert_eq!(message,b"hello");b.write_all(b"reply").await.unwrap();b.shutdown().await.unwrap();let mut response=Vec::new();a.read_to_end(&mut response).await.unwrap();assert_eq!(response,b"reply");assert!(a.write_all(b"late").await.is_err());});});
 test("native owned split Drop sends FIN while read-half remains",||{current().block_on(async{let listener=TcpListener::bind("127.0.0.1:0").await.unwrap();let a=TcpStream::connect(listener.local_addr().unwrap()).await.unwrap();let(mut b,_)=listener.accept().await.unwrap();let(mut read,mut write)=a.into_split();write.write_all(b"split").await.unwrap();drop(write);let mut bytes=Vec::new();b.read_to_end(&mut bytes).await.unwrap();assert_eq!(bytes,b"split");b.write_all(b"kept").await.unwrap();b.shutdown().await.unwrap();let mut kept=Vec::new();read.read_to_end(&mut kept).await.unwrap();assert_eq!(kept,b"kept");});});
 test("native delayed data wakes parked reactor and rearms reads",||{current().block_on(async{let listener=TcpListener::bind("127.0.0.1:0").await.unwrap();let mut a=TcpStream::connect(listener.local_addr().unwrap()).await.unwrap();let(mut b,_)=listener.accept().await.unwrap();let writer=tokio::spawn(async move{for byte in b"edges"{tokio::time::sleep(Duration::from_millis(2)).await;a.write_all(&[*byte]).await.unwrap();}a.shutdown().await.unwrap();});let mut bytes=Vec::new();tokio::time::timeout(Duration::from_secs(1),b.read_to_end(&mut bytes)).await.unwrap().unwrap();assert_eq!(bytes,b"edges");writer.await.unwrap();});});
 test("native refused connection propagates error",||{current().block_on(async{assert!(TcpStream::connect("127.0.0.1:39999").await.is_err());});});
 test("native cancelled accept removes reactor registration",||{current().block_on(async{let listener=TcpListener::bind("127.0.0.1:0").await.unwrap();let j=tokio::spawn(async move{listener.accept().await});tokio::task::yield_now().await;j.abort();assert!(j.await.unwrap_err().is_cancelled());});});
 test("native stream reports original runtime shutdown",||{let rt=current();let(mut stream,peer,listener)=rt.block_on(async{let listener=TcpListener::bind("127.0.0.1:0").await.unwrap();let a=TcpStream::connect(listener.local_addr().unwrap()).await.unwrap();let(b,_)=listener.accept().await.unwrap();(a,b,listener)});drop(rt);current().block_on(async{let mut buf=[0;1];let error=stream.read(&mut buf).await.unwrap_err();assert!(tokio::runtime::is_rt_shutdown_err(&error));});drop((stream,peer,listener));});
 test("native UDP datagram peek/source/truncation preserves boundaries",||{current().block_on(async{let a=UdpSocket::bind("127.0.0.1:0").await.unwrap();let b=UdpSocket::bind("127.0.0.1:0").await.unwrap();a.send_to(b"packet",b.local_addr().unwrap()).await.unwrap();assert_eq!(b.peek_sender().await.unwrap(),a.local_addr().unwrap());let mut first=[0;3];let(n,from)=b.peek_from(&mut first).await.unwrap();assert_eq!(n,3);assert_eq!(from,a.local_addr().unwrap());assert_eq!(&first,b"pac");let(n,_)=b.recv_from(&mut first).await.unwrap();assert_eq!(n,3);assert!(tokio::time::timeout(Duration::from_millis(2),b.recv_from(&mut first)).await.is_err());});});
 test("native connected UDP filters queued and incoming foreign sources",||{current().block_on(async{let a=UdpSocket::bind("127.0.0.1:0").await.unwrap();let b=UdpSocket::bind("127.0.0.1:0").await.unwrap();let alien=UdpSocket::bind("127.0.0.1:0").await.unwrap();let addr=b.local_addr().unwrap();alien.send_to(b"queued",addr).await.unwrap();b.connect(a.local_addr().unwrap()).await.unwrap();alien.send_to(b"future",addr).await.unwrap();a.connect(addr).await.unwrap();a.send(b"valid").await.unwrap();let mut buf=[0;8];assert_eq!(b.peek(&mut buf).await.unwrap(),5);assert_eq!(&buf[..5],b"valid");assert_eq!(b.recv(&mut buf).await.unwrap(),5);assert!(tokio::time::timeout(Duration::from_millis(2),b.recv(&mut buf)).await.is_err());});});
 test("native socket options reach actual service and unsupported ones fail",||{current().block_on(async{let listener=TcpListener::bind("127.0.0.1:0").await.unwrap();let a=TcpStream::connect(listener.local_addr().unwrap()).await.unwrap();let(_b,_)=listener.accept().await.unwrap();assert!(!a.nodelay().unwrap());a.set_nodelay(true).unwrap();assert!(a.nodelay().unwrap());a.set_ttl(37).unwrap();assert_eq!(a.ttl().unwrap(),37);assert!(a.set_ttl(0).is_err());assert!(a.set_zero_linger().is_err());let udp=UdpSocket::bind("127.0.0.1:0").await.unwrap();udp.set_ttl(23).unwrap();assert_eq!(udp.ttl().unwrap(),23);assert!(udp.set_broadcast(true).is_err());assert!(udp.set_tos_v4(12).is_err());});});
 test("native address lookup keeps numeric IPv4/IPv6 fast paths",||{current().block_on(async{let before=network_boundary::DNS_CALLS.load(Ordering::Relaxed);let v4=tokio::net::lookup_host("127.0.0.1:45").await.unwrap().collect::<Vec<_>>();assert_eq!(v4,["127.0.0.1:45".parse().unwrap()]);let v6=tokio::net::lookup_host(("::1",46)).await.unwrap().collect::<Vec<_>>();assert_eq!(v6,["[::1]:46".parse().unwrap()]);assert_eq!(network_boundary::DNS_CALLS.load(Ordering::Relaxed),before);});});
 test("native DNS uses blocking thread and preserves typed failures",||{current().block_on(async{let before=network_boundary::DNS_CALLS.load(Ordering::Relaxed);let addrs=tokio::net::lookup_host("native.test:87").await.unwrap().collect::<Vec<_>>();assert_eq!(addrs,["127.0.0.1:87".parse().unwrap()]);let err=tokio::net::lookup_host(("timeout.test",99)).await.unwrap_err();assert_eq!(err.kind(),trueos_runtime::io::ErrorKind::TimedOut);assert_eq!(network_boundary::DNS_CALLS.load(Ordering::Relaxed)-before,2);});});
 println!("12 native-network behavior cases passed (host ABI simulation)");boundary::cleanup_tls();
}
